const item = $input.first();
const input = item.json || {};
const parseObject = (raw, fallback) => {
  if (raw === undefined || raw === null || raw === '') return fallback;
  if (typeof raw === 'object' && !Array.isArray(raw)) return raw;
  if (typeof raw !== 'string') return fallback;
  const text = raw.trim();
  if (!text) return fallback;
  try {
    const parsed = JSON.parse(text);
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : fallback;
  } catch {
    return { prompt: text };
  }
};
const rawRequest = typeof input.request === 'string' ? input.request.trim() : '';
const request = parseObject(input.request, rawRequest ? { prompt: rawRequest } : {});
const rawAnswer = typeof input.clarification_response === 'string' ? input.clarification_response.trim() : '';
const clarificationResponse = rawAnswer ? parseObject(rawAnswer, null) : null;
const sessionId = typeof input.session_id === 'string' ? input.session_id.trim() : '';
const file = item.binary?.file;
return [{
  json: {
    request,
    session_id: sessionId || undefined,
    clarification_response: clarificationResponse,
    entrypoint: 'form',
  },
  binary: file ? { file } : undefined,
}];

const result = $input.first().json || {};
const escapeHtml = (value) => String(value ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/\"/g, '&quot;')
  .replace(/'/g, '&#39;');
const prettyJson = (value, limit = 16000) => {
  let text;
  try { text = JSON.stringify(value, null, 2); } catch { text = String(value); }
  return text.length > limit ? `${text.slice(0, limit)}\n… truncated for display` : text;
};
const status = escapeHtml(result.status || 'error');
const message = escapeHtml(result.message || 'The workflow did not return a message.');
const sessionId = escapeHtml(result.session_id || result.meta?.session_id || '');
const artifact = escapeHtml(result.data?.artifact_ref || '');
const clarification = result.clarification && typeof result.clarification === 'object' ? result.clarification : null;
const details = {
  status: result.status || 'error',
  session_id: result.session_id || result.meta?.session_id || null,
  data: result.data || null,
  filters_applied: result.filters_applied || [],
  warnings: result.warnings || [],
  errors: result.errors || [],
  clarification: clarification,
};
const clarificationBlock = clarification
  ? `<h2>Clarification required</h2><p>Session ID: <code>${sessionId}</code></p><p>Token: <code>${escapeHtml(clarification.token || '')}</code></p><pre>${escapeHtml(prettyJson(clarification.questions || []))}</pre><p>Submit this form again with the session ID and a JSON clarification answer. Do not upload the workbook again.</p>`
  : '';
const artifactBlock = artifact ? `<p>Artifact reference: <code>${artifact}</code></p>` : '';
const html = `<main><h1>Excel extraction result</h1><p>Status: <strong>${status}</strong></p><p>${message}</p>${sessionId ? `<p>Session ID: <code>${sessionId}</code></p>` : ''}${artifactBlock}${clarificationBlock}<details><summary>Structured response</summary><pre>${escapeHtml(prettyJson(details))}</pre></details></main>`;
return [{ json: { ...result, form_response_html: html } }];
